sys_script_include.script:
var AutoMedUtils = Class.create();
AutoMedUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getScheduleDetails: function() {
        var scheduleId = this.getParameter("sysparm_schedule_id");
        var gr = new GlideRecord("x_snc_trackmed_medication_schedule_table");
        if (gr.get(scheduleId)) {
            var result = {
                patient: gr.getValue("patient"),
                caretaker: gr.getValue("caretaker"),
                medication: gr.getValue("medication_name"),
                frequency: gr.getValue("frequency")
            };
            return JSON.stringify(result);
        }
        return JSON.stringify({});
    },
    getLowStockSchedules: function() {
        var results = [];
        var gr = new GlideRecord("x_snc_trackmed_medication_schedule_table");
        gr.addQuery("state", "active");
        gr.addEncodedQuery(
            "stock_quantityLEFIELDlow_stock_threshold");
        gr.query();
        while (gr.next()) {
            results.push({
                sysId: gr.getUniqueValue(),
                patient: gr.getDisplayValue("patient"),
                medication: gr.getValue("medication_name"),
                stock: gr.getValue("stock_quantity")
            });
        }
        return JSON.stringify(results);
    },
    type: "AutoMedUtils"
});
